#!/usr/bin/python3
from pathlib import Path
import hashlib
import sys
import xml.etree.ElementTree as ET

SOURCE = Path("/workspace/Incident_Handoff_Source.fodt")
REFERENCE = Path("/tests/Incident_Handoff_Source.reference.fodt")
OUTPUT = Path("/home/user/Desktop/Incident_Handoff_Final.fodt")
NS = {
    "office": "urn:oasis:names:tc:opendocument:xmlns:office:1.0",
    "style": "urn:oasis:names:tc:opendocument:xmlns:style:1.0",
    "text": "urn:oasis:names:tc:opendocument:xmlns:text:1.0",
    "fo": "urn:oasis:names:tc:opendocument:xmlns:xsl-fo-compatible:1.0",
}
T = "{" + NS["text"] + "}"
S = "{" + NS["style"] + "}"
FO = "{" + NS["fo"] + "}"

EXPECTED = [
    "Service Incident Handoff",
    "Prepared for the morning operations lead",
    "",
    "Current status",
    "Checkout latency is stable, and the payment queue is draining normally.",
    "",
    "Watch closely",
    "Escalate immediately if queue depth exceeds 1,200 messages.",
    "",
    "Owner and next update",
    "Maya Chen owns the watch until 09:30 UTC.",
    "Next update: 09:00 UTC in the operations channel.",
]
BOLD_TEXT = "queue depth exceeds 1,200 messages"
ITALIC_TEXT = "Next update: 09:00 UTC in the operations channel."


def fail(message):
    print(f"verification failed: {message}", file=sys.stderr)
    raise SystemExit(1)


def digest(path):
    return hashlib.sha256(path.read_bytes()).hexdigest()


if not SOURCE.is_file() or not REFERENCE.is_file():
    fail("source draft or private reference is missing")
if digest(SOURCE) != digest(REFERENCE):
    fail("the source draft was modified")
if not OUTPUT.is_file():
    fail(f"final Writer document is missing at {OUTPUT}")
if OUTPUT.stat().st_size > 2_000_000:
    fail("final document is unexpectedly large")

try:
    root = ET.parse(OUTPUT).getroot()
except (ET.ParseError, OSError) as exc:
    fail(f"final artifact is not readable Flat XML ODF: {exc}")
if root.tag != "{" + NS["office"] + "}document" or root.get("{" + NS["office"] + "}mimetype") != "application/vnd.oasis.opendocument.text":
    fail("final artifact is not a Flat XML ODF Writer document")

body = root.find("office:body/office:text", NS)
if body is None:
    fail("ODF document has no Writer text body")


def visible_text(element):
    return "".join(element.itertext()).replace("\u00a0", " ").strip()


paragraphs = [(e, visible_text(e)) for e in body.iter() if e.tag in (T + "p", T + "h")]
actual = [text for _, text in paragraphs]
while actual and actual[-1] == "":
    actual.pop()
if actual != EXPECTED:
    fail(f"paragraph text/order differs; found {actual!r}")

by_text = {text: element for element, text in paragraphs if text}
for text, wanted in {
    "Service Incident Handoff": "1",
    "Current status": "2",
    "Watch closely": "2",
    "Owner and next update": "2",
}.items():
    element = by_text.get(text)
    level = element.get(T + "outline-level") if element is not None else None
    if element is None or element.tag != T + "h" or level != wanted:
        fail(f"{text!r} is not a Writer Heading {wanted} paragraph")

# Resolve text and paragraph style inheritance, because Writer may serialize
# direct formatting as an automatic text style or as a paragraph-level style.
styles = {}
for style in root.iter(S + "style"):
    name = style.get(S + "name")
    if not name:
        continue
    props = style.find("style:text-properties", NS)
    styles[name] = {
        "parent": style.get(S + "parent-style-name"),
        "weight": props.get(FO + "font-weight") if props is not None else None,
        "italic": props.get(FO + "font-style") if props is not None else None,
    }


def effective(style_name, prop):
    seen = set()
    while style_name and style_name not in seen:
        seen.add(style_name)
        info = styles.get(style_name, {})
        value = info.get(prop)
        if value is not None:
            return value
        style_name = info.get("parent")
    return None


def styled_fragments(element, inherited_style=None):
    style_name = element.get(T + "style-name", inherited_style)
    if element.text:
        yield element.text, style_name
    for child in element:
        yield from styled_fragments(child, style_name)
        if child.tail:
            yield child.tail, style_name


escalation = by_text["Escalate immediately if queue depth exceeds 1,200 messages."]
fragments = list(styled_fragments(escalation, escalation.get(T + "style-name")))
bold_joined = "".join(text for text, style in fragments if effective(style, "weight") == "bold")
if bold_joined != BOLD_TEXT:
    fail(f"the exact escalation phrase is not the only bold text in its paragraph; bold text={bold_joined!r}")

final_line = by_text[ITALIC_TEXT]
fragments = list(styled_fragments(final_line, final_line.get(T + "style-name")))
italic_joined = "".join(text for text, style in fragments if effective(style, "italic") == "italic")
if italic_joined != ITALIC_TEXT:
    fail(f"the complete final line is not italic; italic text={italic_joined!r}")

if digest(OUTPUT) == digest(SOURCE):
    fail("final artifact is unchanged from the draft")
print("verified source integrity, exact content, heading hierarchy, and native emphasis")
